package com.citacloud.app.views; import com.citacloud.app.models.Cita; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.time.LocalDate; import java.util.*;
@Route(value="check-in",layout=MainLayout.class) @PageTitle("Check-in | CitaCloud") @PermitAll public class CheckInView extends VerticalLayout {public CheckInView(CitaService citas,CheckInService checkins){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);add(new H2("Check-in"),new Paragraph("Registre la llegada de pacientes con cita confirmada para hoy."));Grid<Cita> grid=new Grid<>(Cita.class,false);grid.addColumn(c->c.getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(c->c.getPaciente().getDocumento()).setHeader("DOCUMENTO");grid.addColumn(c->c.getMedico().getNombreCompleto()).setHeader("MÉDICO");grid.addColumn(Cita::getHoraInicio).setHeader("HORA");grid.addComponentColumn(c->{Button b=new Button("Registrar llegada",e->{try{checkins.registrar(empresa,u.getUsuarioId(),c.getId());Notification.show("Llegada registrada.");getUI().ifPresent(ui->ui.getPage().reload());}catch(Exception x){Notification.show(x.getMessage());}});return b;}).setHeader("ACCIÓN");grid.setItems(empresa==null?List.of():citas.listarPorFecha(empresa,LocalDate.now()).stream().filter(c->"CONFIRMADA".equals(c.getEstado())).toList());grid.setWidthFull();add(grid);}}
